package com.nanless.paperdigest.ui
import com.nanless.paperdigest.data.Article
import com.nanless.paperdigest.data.ArticleResource
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test
class SessionPresentationTest {
 @Test fun jobOpensExactSessionWithoutCurrentPaperOrLatestFallback(){val old=JSONObject().put("id","old").put("paperID","p1").put("answer","original");val newer=JSONObject().put("id","new").put("paperID","p1").put("answer","newer");assertSame(old,jobSession(JSONObject().put("id","job").put("sessionID","old"),listOf(newer,old)));assertSame(old,jobSession(JSONObject().put("id","old"),listOf(newer,old)));assertNull(jobSession(JSONObject().put("id","missing").put("paperID","p1"),listOf(newer,old)));assertNull(jobSession(JSONObject().put("id","old").put("sessionID","missing"),listOf(old)))}
 @Test fun rawObjectIsNotInventedAsAnswerAndLegacyTextIsRead(){assertEquals("saved",sessionAnswer(JSONObject().put("text","saved")));assertEquals("",sessionAnswer(JSONObject().put("response",JSONObject().put("secret","never rendered as answer"))));assertEquals("original",sessionAnswer(JSONObject().put("answer","original").put("response","other")))}
 @Test fun recoveryOnlyOfferedForIssuedAndroidOriginalIncompleteRecords(){val s=JSONObject().put("inputContract","android-study-input-v1").put("requestIssued",true).put("status","interrupted");assertTrue(canRecoverSession(s));assertFalse(canRecoverSession(JSONObject(s.toString()).put("requestIssued",false)));assertFalse(canRecoverSession(JSONObject(s.toString()).put("status","completed")));assertFalse(canRecoverSession(JSONObject(s.toString()).put("inputContract","mac-other")))}
 @Test fun copiedNoteKeepsOriginalQuestionAnswerSourceAndUnknownFee(){val s=JSONObject().put("id","original-id").put("paperID","original-owner").put("question","original-question").put("answer","original-answer").put("requestIssued",true).put("charge","unknown").put("inputSHA256","a".repeat(64)).put("source",JSONObject().put("kind","pdf-range").put("pages",org.json.JSONArray(listOf(2,3))).put("sourceVersion","v1"));val before=s.toString();val appended="existing note"+noteFromSession(s);assertTrue(appended.startsWith("existing note"));for(text in listOf("original-id","original-question","original-answer","v1","2、3","a".repeat(64)))assertTrue(appended.contains(text));assertEquals("金额未确认，不表示免费",sessionChargeLabel(s));assertEquals(before,s.toString())}
 @Test fun publicShareContainsOnlyOriginalTitleAndValidatedHttpsSource(){assertEquals("Original\nhttps://arxiv.org/abs/2501.00001",publicShareText("Original","https://arxiv.org/abs/2501.00001"));for(url in listOf("file:///private/note","content://private/data","javascript:alert(1)","https://secret@example.org")){assertFalse(publicShareURL(url));assertThrows(IllegalArgumentException::class.java){publicShareText("Original",url)}}}
 @Test fun ordinaryInformationIsNotAnErrorAndMissingAssetsAreExplicit(){val a=Article("p","<p>x</p>","x","https://example.org","https://example.org","a".repeat(64),"2026-10-25",completeOffline=true,notices=listOf("应用内样稿"));assertEquals("info",noticeTone(a));assertEquals("warning",noticeTone(a.copy(isStale=true)));assertEquals("error",noticeTone(a.copy(resources=listOf(ArticleResource("https://example.org/image",missingReason="保存失败"))))) }
}
